#include <torch/extension.h>
#include <hip/hip_runtime.h>

// Optimized kernel with warp-level reductions and register reuse
__global__ void gated_deltanet_recurrence_kernel(
    const float* __restrict__ q,      // (batch, seq, heads, d_qk)
    const float* __restrict__ k,      // (batch, seq, heads, d_qk)
    const float* __restrict__ v,      // (batch, seq, heads, d_v)
    const float* __restrict__ alpha,  // (batch, seq, heads)
    const float* __restrict__ beta,   // (batch, seq, heads)
    float* __restrict__ state,        // (batch, heads, d_v, d_qk)
    float* __restrict__ output,       // (batch, seq, heads, d_v)
    int batch_size,
    int seq_len,
    int num_heads,
    int d_qk,
    int d_v
) {
    int batch_idx = blockIdx.x;
    int head_idx = blockIdx.y;

    if (batch_idx >= batch_size || head_idx >= num_heads) return;

    extern __shared__ float shared_mem[];
    float* k_shared = shared_mem;
    float* v_shared = k_shared + d_qk;
    float* S_k = v_shared + d_v;
    float* q_shared = S_k + d_v;

    int tid = threadIdx.x;
    int block_size = blockDim.x;
    int state_size = d_v * d_qk;

    float* S = state + (batch_idx * num_heads + head_idx) * state_size;

    // Initialize state
    for (int i = tid; i < state_size; i += block_size) {
        S[i] = 0.0f;
    }
    __syncthreads();

    // Process timesteps
    for (int t = 0; t < seq_len; t++) {
        int qkv_base = ((batch_idx * seq_len + t) * num_heads + head_idx);
        int ab_idx = (batch_idx * seq_len + t) * num_heads + head_idx;

        // Load k and v
        for (int i = tid; i < d_qk; i += block_size) {
            k_shared[i] = k[qkv_base * d_qk + i];
        }
        for (int i = tid; i < d_v; i += block_size) {
            v_shared[i] = v[qkv_base * d_v + i];
        }
        __syncthreads();

        float alpha_t = alpha[ab_idx];
        float beta_t = beta[ab_idx];

        // Compute S_k = S @ k with loop unrolling
        for (int i = tid; i < d_v; i += block_size) {
            float sum = 0.0f;
            int base = i * d_qk;

            // Unroll by 16 for d_qk=128
            #pragma unroll 16
            for (int j = 0; j < d_qk; j++) {
                sum += S[base + j] * k_shared[j];
            }
            S_k[i] = sum;
        }
        __syncthreads();

        // Update state: S = alpha * S - beta * (S_k - v) @ k^T
        // Process multiple elements per thread for better efficiency
        for (int idx = tid; idx < state_size; idx += block_size) {
            int i = idx / d_qk;
            int j = idx % d_qk;
            float error_i = S_k[i] - v_shared[i];
            S[idx] = __fmaf_rn(-beta_t * error_i, k_shared[j], alpha_t * S[idx]);
        }
        __syncthreads();

        // Load q
        for (int i = tid; i < d_qk; i += block_size) {
            q_shared[i] = q[qkv_base * d_qk + i];
        }
        __syncthreads();

        // Output computation
        int out_base = qkv_base * d_v;
        for (int i = tid; i < d_v; i += block_size) {
            float sum = 0.0f;
            int base = i * d_qk;

            #pragma unroll 16
            for (int j = 0; j < d_qk; j++) {
                sum += S[base + j] * q_shared[j];
            }
            output[out_base + i] = sum;
        }
        __syncthreads();
    }
}

