    for (int i = tid; i < d_v * d_qk; i += block_size) {
        S[i] = 0.0f;
    }
    __syncthreads();

    // Process each timestep
    for (int t = 0; t < seq_len; t++) {
        int qkv_base = ((batch_idx * seq_len + t) * num_heads + head_idx);
        int alpha_beta_idx = (batch_idx * seq_len + t) * num_heads + head_idx;

        // Load k and v
        for (int i = tid; i < d_qk; i += block_size) {
            k_shared[i] = k[qkv_base * d_qk + i];
        }
        for (int i = tid; i < d_v; i += block_size) {
            v_shared[i] = v[qkv_base * d_v + i];
        }
        __syncthreads();

        float alpha_t = alpha[alpha_beta_idx];
        float beta_t = beta[alpha_beta_idx];

        // Compute S @ k -> S_k
        for (int i = tid; i < d_v; i += block_size) {
            float sum = 0.0f;
            for (int j = 0; j < d_qk; j++) {
                sum += S[i * d_qk + j] * k_shared[j];
            }
            S_k[i] = sum;
        }
        __syncthreads();

        // Update state: S = alpha * S - beta * (S_k - v) @ k^T
        for (int idx = tid; idx < d_v * d_qk; idx += block_size) {
            int i = idx / d_qk;
            int j = idx % d_qk;
            float error_i = S_k[i] - v_shared[i];
            S[idx] = alpha_t * S[idx] - beta_t * error_i * k_shared[j];
        }
        __syncthreads();

        // Load q
        for (int i = tid; i < d_qk; i += block_size) {
            q_shared[i] = q[qkv_base * d_qk + i];
        }
        __syncthreads();

        // Compute output: o = S @ q
        int out_base = qkv_base * d_v;
        for (int i = tid; i < d_v; i += block_size) {
            float sum = 0.0f;
            for (int j = 0; j < d_qk; j++) {
                sum += S[i * d_qk + j] * q_shared[j];
            }
            output[out_base + i] = sum;
        }
        __syncthreads();
    }
}

