# Optimized kernel with better memory access pattern - transpose state for coalescing
gated_deltanet_cpp_source = """
#include <torch/extension.h>
#include <hip/hip_runtime.h>

// Store state as (d_qk, d_v) instead of (d_v, d_qk) for better coalescing
// When computing S @ k, we read along d_qk dimension (now contiguous)
__global__ void gated_deltanet_recurrence_kernel(
    const float* __restrict__ q,      // (batch, seq, heads, d_qk)
    const float* __restrict__ k,      // (batch, seq, heads, d_qk)
    const float* __restrict__ v,      // (batch, seq, heads, d_v)
    const float* __restrict__ alpha,  // (batch, seq, heads)
    const float* __restrict__ beta,   // (batch, seq, heads)
    float* __restrict__ state,        // (batch, heads, d_qk, d_v) - transposed
    float* __restrict__ output,       // (batch, seq, heads, d_v)
    int batch_size,
    int seq_len,
    int num_heads,
    int d_qk,
    int d_v
) {
    int batch_idx = blockIdx.x;
    int head_idx = blockIdx.y;

    if (batch_idx >= batch_size || head_idx >= num_heads) return;

    extern __shared__ float shared_mem[];
    float* k_shared = shared_mem;
    float* v_shared = k_shared + d_qk;
    float* S_k = v_shared + d_v;
    float* q_shared = S_k + d_v;

    int tid = threadIdx.x;
    int block_size = blockDim.x;
    int state_size = d_qk * d_v;

    // State is now (d_qk, d_v) for this (batch, head)
    float* S = state + (batch_idx * num_heads + head_idx) * state_size;

    // Initialize state
    for (int i = tid; i < state_size; i += block_size) {
        S[i] = 0.0f;
    }
    __syncthreads();

    for (int t = 0; t < seq_len; t++) {
        int qkv_base = ((batch_idx * seq_len + t) * num_heads + head_idx);
        int ab_idx = (batch_idx * seq_len + t) * num_heads + head_idx;

        // Load k and v
        for (int i = tid; i < d_qk; i += block_size) {
            k_shared[i] = k[qkv_base * d_qk + i];
        }
        for (int i = tid; i < d_v; i += block_size) {
            v_shared[i] = v[qkv_base * d_v + i];
        }
        __syncthreads();

        float alpha_t = alpha[ab_idx];
        float beta_t = beta[ab_idx];

        // Compute S_k = S^T @ k = k^T @ S
        // S is (d_qk, d_v), so S^T is (d_v, d_qk)
        // S^T @ k: (d_v, d_qk) @ (d_qk,) = (d_v,)
        // Same as: for each v_idx, sum over qk_idx: S[qk_idx, v_idx] * k[qk_idx]
        for (int v_idx = tid; v_idx < d_v; v_idx += block_size) {
            float sum = 0.0f;
            #pragma unroll 8
            for (int qk_idx = 0; qk_idx < d_qk; qk_idx++) {
                sum += S[qk_idx * d_v + v_idx] * k_shared[qk_idx];
            }
            S_k[v_idx] = sum;
        }
        __syncthreads();

        // Update state: S^T = alpha * S^T - beta * (S_k - v) @ k^T
        // In transposed form: S = alpha * S - beta * k @ (S_k - v)^T
        // S[qk_idx, v_idx] = alpha * S[qk_idx, v_idx] - beta * k[qk_idx] * (S_k[v_idx] - v[v_idx])
        for (int idx = tid; idx < state_size; idx += block_size) {
            int qk_idx = idx / d_v;
            int v_idx = idx % d_v;
            float error = S_k[v_idx] - v_shared[v_idx];
            S[idx] = alpha_t * S[idx] - beta_t * k_shared[qk_idx] * error;
        }
        __syncthreads();

        // Load q
        for (int i = tid; i < d_qk; i += block_size) {
            q_shared[i] = q[qkv_base * d_qk + i];
        }
        __syncthreads();

        // Output = S^T @ q
        // S^T @ q: (d_v, d_qk) @ (d_qk,) = (d_v,)
        int out_base = qkv_base * d_v;
        for (int v_idx = tid; v_idx < d_v; v_idx += block_size) {
            float sum = 0.0f;
            #pragma unroll 8
            for (int qk_idx = 0; qk_idx < d_qk; qk_idx++) {
                sum += S[qk_idx * d_v + v_idx] * q_shared[qk_idx];
            }
            output[out_base + v_idx] = sum;
        }
        __syncthreads();
    }
